import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.Boholvbs.js";const g=JSON.parse('{"title":"Agents & modes","description":"Built-in build/plan/auto agents, subagents like explore and general, custom agents in markdown, and per-agent models and permissions.","frontmatter":{"title":"Agents & modes","description":"Built-in build/plan/auto agents, subagents like explore and general, custom agents in markdown, and per-agent models and permissions."},"headers":[],"relativePath":"using/agents.md","filePath":"using/agents.md"}'),n={name:"using/agents.md"};function o(d,e,l,r,p,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<p>An <strong>agent</strong> is PrioriCode&#39;s job description: a system prompt, a model, and a permission profile — bundled with a personality. Switching agents changes what the assistant is allowed to do <em>and</em> how it approaches the work.</p><h2 id="the-built-ins" tabindex="-1">The built-ins <a class="header-anchor" href="#the-built-ins" aria-label="Permalink to &quot;The built-ins&quot;">​</a></h2><p>Press <code>tab</code> to cycle primaries (or <code>/agents</code>, or <code>--agent name</code> on the CLI):</p><table tabindex="0"><thead><tr><th>Agent</th><th>Mode</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><code>build</code></td><td>primary</td><td>The default. Executes tools based on your configured permissions. This is the &quot;do the work&quot; agent.</td></tr><tr><td><code>plan</code></td><td>primary</td><td>Read-only. All edit tools are denied — except one: its plan file. Reads, greps, explores, and writes a plan; then asks to switch back.</td></tr><tr><td><code>auto</code></td><td>primary</td><td>Automation mode. Explores, plans, and executes without user interaction, auto-committing each verified phase. For unattended runs.</td></tr><tr><td><code>general</code></td><td>subagent</td><td>Complex search and multistep tasks. Lives as a child session; can&#39;t touch your todos.</td></tr><tr><td><code>explore</code></td><td>subagent</td><td>Read-only scout: grep, glob, read, bash (careful), web. Great for &quot;find everything that touches X&quot;.</td></tr></tbody></table><p>A few hidden workers run the machinery for you — <code>title</code> (names your sessions), <code>summary</code>, <code>compaction</code>, and the coordination <code>responder</code>. You&#39;ll see them in transcripts; you don&#39;t switch to them.</p><h3 id="plan-mode-properly" tabindex="-1">Plan mode, properly <a class="header-anchor" href="#plan-mode-properly" aria-label="Permalink to &quot;Plan mode, properly&quot;">​</a></h3><p><code>plan</code> is not &quot;please behave&quot; — it&#39;s enforced. Edits are denied by rule; the only file it may write is the plan itself:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;prioricode/plans directory&gt;/.prioricode/plans/&lt;date&gt;-&lt;slug&gt;.md    # in a repo</span></span>
<span class="line"><span>&lt;data dir&gt;/plans/…                                                  # outside one</span></span></code></pre></div><p>The model can also <em>propose</em> mode changes: from <code>build</code>, <code>plan_enter</code> asks to switch into planning; from <code>plan</code>, <code>plan_exit</code> asks to switch to <code>build</code> and start implementing — accepting it injects an &quot;approved, go build it&quot; message with your answer. Say no, and planning continues. That handshake is the feature: the plan gets read before the code gets written.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start a fresh session with <code>prioricode --agent plan</code>, let it write the plan, review the <code>.md</code> like any other file, then approve the switch. You&#39;ll ship fewer &quot;wait, why did you rewrite that?&quot; moments.</p></div><h2 id="subagents" tabindex="-1">Subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;Subagents&quot;">​</a></h2><p>Subagents run as <strong>child sessions</strong> with their own context — the parent delegates, the child reports back. The agent invokes them with the <code>task</code> tool; you can nudge one in with an <code>@general</code>-style mention, and once a session exists you can watch its transcript directly (child-session navigation is on the <a href="./sessions.html">sessions page</a>).</p><p>Two knobs matter:</p><ul><li><strong><code>subagent_depth</code></strong> (config, default <code>1</code>) — how deep subagents may recurse. At 1, a subagent can&#39;t spawn its own subagents. Good default; raise it only when you trust the plan.</li><li><strong>Background subagents</strong> — experimental. <code>ctrl+b</code> backgrounds running synchronous subagents so the parent keeps working; results land back in the conversation when they finish. Requires <code>PRIORICODE_EXPERIMENTAL_BACKGROUND_SUBAGENTS=1</code>.</li></ul><p>By default subagents are denied <code>todowrite</code> and <code>task</code> (no stealing the parent&#39;s checklist or grandkid agents) unless their permissions say otherwise.</p><h2 id="custom-agents" tabindex="-1">Custom agents <a class="header-anchor" href="#custom-agents" aria-label="Permalink to &quot;Custom agents&quot;">​</a></h2><p>A custom agent is a markdown file. Drop it in <code>.prioricode/agents/</code> (project) or <code>~/.config/prioricode/agents/</code> (global — any config dir works, and the file&#39;s path in the folder becomes the name):</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Security review pass over a diff or directory</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">primary</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic/claude-sonnet-4-5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">temperature</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  edit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deny</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  bash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;git diff*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">allow</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ask</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  webfetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">allow</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#f87171&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a security reviewer. Read the target code, hunt for injection, auth,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">and secrets-handling issues, and report by severity — with file:line evidence.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Never edit files; propose fixes in the report.</span></span></code></pre></div><p>The body is the system prompt. Frontmatter fields: <code>description</code>, <code>mode</code> (<code>primary</code> | <code>subagent</code> | <code>all</code>), <code>model</code>, <code>variant</code>, <code>temperature</code>, <code>top_p</code>, <code>steps</code> (max agentic steps), <code>hidden</code>, <code>color</code>, <code>options</code> (passthrough to the provider), and <code>permission</code> (full ruleset — see <a href="./permissions.html">permissions</a>). Unknown keys are passed to the provider as options, so typos don&#39;t fail loudly — keep the file tidy.</p><p>Or let the machine write it for you:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # interactive: description, mode, tools, model</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # what&#39;s registered, and where it stands</span></span></code></pre></div><p><code>create</code> writes the file with a locked-down permission set — every tool you didn&#39;t select is denied, which is the right bias for a specialist.</p><p>Registering in config instead of markdown works too — <code>agent</code> is a map of the same keys (<code>agent.my-reviewer.model</code>, <code>agent.my-reviewer.permission</code>, <code>disable: true</code> to remove any agent, built-in or custom). See <a href="./../reference/config.html#agent">config reference</a>.</p><h3 id="picking-a-default" tabindex="-1">Picking a default <a class="header-anchor" href="#picking-a-default" aria-label="Permalink to &quot;Picking a default&quot;">​</a></h3><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;default_agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>The default agent must be a visible primary. <code>tab</code> still gets you everywhere.</p><h2 id="models-per-agent" tabindex="-1">Models per agent <a class="header-anchor" href="#models-per-agent" aria-label="Permalink to &quot;Models per agent&quot;">​</a></h2><p><code>agent.&lt;name&gt;.model</code> pins an agent to a model (<code>variant</code> optional); when a subagent is dispatched, it uses its own configured model, falling back to the parent&#39;s current one. Practical pattern: <code>build</code> on a strong model, <code>explore</code> on something cheap and fast — see <a href="./../getting-started/providers.html">providers &amp; models</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./permissions.html">Permissions</a> — The rules each agent profile leans on. <ul><li><a href="./../reference/tools.html">Tools</a> — What the agent can actually execute.</li><li><a href="./headless.html">Headless</a> — <code>--agent</code> for CI and scripts.</li><li><a href="./../extending/skills.html">Skills</a> — Teach an agent a procedure without forking it.</li></ul></li></ul>`,30)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
